#!/usr/bin/env python3
"""Build a standalone interactive offline HTML preview of the native pose editor."""
import re,json, pathlib
root=pathlib.Path(__file__).resolve().parents[1]
src=(root/'Mozdulj.Core/PoseTemplates.cs').read_text()
names=['head','neck','leftShoulder','rightShoulder','leftElbow','rightElbow','leftWrist','rightWrist','leftHip','rightHip','leftKnee','rightKnee','leftAnkle','rightAnkle','leftToe','rightToe']
positions={}
for key, raw in re.findall(r'"([\w-]+)"\s*=>\s*M\(\[([^\]]+)\]\)',src):
 v=list(map(float,re.findall(r'-?\d+(?:\.\d+)?',raw)))
 positions[key]={names[i]:{'x':v[3*i],'y':v[3*i+1],'z':v[3*i+2]} for i in range(16)}
positions['standing']={names[i]:{'x':v,'y':y,'z':z} for i,(v,y,z) in enumerate([(50,14,0),(50,25,0),(39,29,-3),(61,29,3),(35,47,-3),(65,47,3),(34,64,-3),(66,64,3),(44,57,-3),(56,57,3),(43,74,-3),(57,74,3),(42,91,-3),(58,91,3),(34,94,-3),(66,94,3)])}
named=[('standing','Állás'),('cross-legged','Törökülés'),('chair-seated','Ülés széken'),('long-sitting','Nyújtott ülés'),('butterfly','Pillangóülés'),('side-lying','Oldalfekvés'),('supine','Hanyattfekvés'),('quadruped','Négykézláb'),('child-pose','Gyermekpóz'),('plank','Plank'),('lunge','Kitörés'),('single-leg','Egylábas állás'),('wall-standing','Falnál állás')]
assert all(k in positions for k,_ in named)
catalog=json.loads((root/'Mozdulj.Maui/Resources/Raw/exercises.catalog.json').read_text())['exercises']
html=r'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mozdulj! – Pózstúdió és katalógusellenőrző</title>
<style>
:root{--plum:#593778;--purple:#76509c;--teal:#358f94;--lilac:#eee5f6;--ink:#2c2940;--muted:#6d6680}
*{box-sizing:border-box}body{margin:0;background:#f8f6fb;font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink)}header{background:linear-gradient(110deg,#442660,#855ca9);padding:16px 26px;color:white;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}h1{font-size:23px;margin:0}h2{font-size:18px;margin:8px 0 16px}small,p.note{color:var(--muted)}header small{color:#f2e8fc}main{max-width:1220px;margin:22px auto;padding:0 12px}.tabs{display:flex;gap:10px;margin-bottom:14px}.tab{border:1px solid #d7c5ea;background:white;color:#573d7a;padding:10px 20px;border-radius:10px;font-weight:700;cursor:pointer}.tab.on{background:#5d3c80;color:white}section{display:none}section.on{display:block}.layout{display:grid;grid-template-columns:minmax(300px,380px) minmax(350px,1fr);gap:16px}.panel{background:white;padding:20px;border:1px solid #e4dbef;border-radius:20px;box-shadow:0 7px 22px #452c6812}.field{margin:12px 0}label{display:block;font-weight:650;font-size:13px;margin-bottom:5px}select,input,button{font:inherit}select,input[type="range"],input[type="search"]{width:100%}select,input[type="search"]{padding:10px 12px;border:1px solid #d6cae3;border-radius:9px;background:#fff}button{border:0;border-radius:10px;padding:10px 13px;background:#6e4895;color:white;font-weight:650;cursor:pointer}button.secondary{background:#eee7f5;color:#634384}button.negative{background:#f7ebeb;color:#a34151}.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.inline>*{flex:1}.hint{font-size:13px;color:var(--muted);line-height:1.5}.status{min-height:24px;font-size:13px;color:#704e87;margin-top:10px}.board{width:100%;max-width:560px;aspect-ratio:1;background:#fbf8fe;border:1px solid #e4d6ef;border-radius:18px;touch-action:none;display:block;margin:0 auto}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.gallery canvas{width:100%;aspect-ratio:1;background:#faf6fe;border:1px solid #eadff2;border-radius:14px}.scroll-list{height:400px;overflow:auto;border:1px solid #e4dbef;border-radius:12px}.entry{background:white;padding:10px 12px;width:100%;display:block;text-align:left;color:#3f3351;border:0;border-bottom:1px solid #eee7f4;border-radius:0}.entry.on{background:#eae1f6}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.chip{font-size:11px;background:#e9e0f2;color:#6b4186;padding:5px 8px;border-radius:20px}footer{max-width:1220px;margin:10px auto 35px;padding:0 18px;color:#81758a;font-size:12px}
@media(max-width:830px){.layout{grid-template-columns:1fr}.panel{padding:15px}.gallery{grid-template-columns:repeat(2,1fr)}h1{font-size:20px}}
</style></head><body><header><div><h1>Mozdulj! · Pózstúdió</h1><small>v0.13 · interaktív illusztrációs fejlesztői előnézet</small></div><span>Egységes emberalak · eszközök · mozgásfázisok</span></header><main><div class="tabs"><button class="tab on" data-tab="editor">Pózszerkesztő</button><button class="tab" data-tab="audit">132 gyakorlat ellenőrzése</button></div>
<section id="editor" class="on"><div class="layout"><div class="panel"><h2>Sablon és eszközök</h2><div class="field"><label>Sablon</label><select id="template"></select></div><div class="inline"><button id="loadTemplate">Sablon alkalmazása</button><button class="secondary" id="newFrame">Fázis másolása</button></div><div class="field"><label>Aktuális mozgásfázis</label><select id="frame"></select></div><div class="field"><label>Szerkesztési mód</label><select id="mode"><option value="points">Testpontok mozgatása</option><option value="prop">Eszköz mozgatása</option><option value="arrow">Nyíl hozzáadása (két érintés)</option></select></div><div class="field"><label>Eszköz</label><select id="equipment"></select></div><div class="inline"><button class="secondary" id="addEq">+ Eszköz hozzáadása</button><button class="negative" id="removeEq">Kijelölt törlése</button></div><div class="field"><label>Kijelölt eszköz mérete</label><input id="scale" type="range" min="0.5" max="1.6" step="0.05" value="1"></div><div class="field"><label>Kijelölt eszköz elforgatása</label><input id="rotation" type="range" min="-180" max="180" step="5" value="0"></div><div class="inline"><button id="export">Ábra JSON export</button><button class="secondary" id="reset">Visszaállítás</button></div><p class="hint">Az eszközök mérete aránytartó; a pontok csak végtaghossz-korlátok mellett mozgathatók. Az ábrák szemléltetők, nem anatómiai hitelesítések.</p><div class="status" id="status" aria-live="polite"></div></div>
<div class="panel"><h2>Interaktív rajzfelület</h2><canvas class="board" id="canvas" width="560" height="560"></canvas><p class="hint">A türkiz pontokat húzd. Először válassz módot; nyílhoz érints meg két helyet. A rajz mentéskor testpontokat és tárgyakat tárol, nem képfájlt.</p><div class="chips"><span class="chip">16 testpont / fázis</span><span class="chip">Összekapcsolt végtagok</span><span class="chip">0,5–1,6× eszközméret</span><span class="chip">Offline JSON</span></div></div></div></section>
<section id="audit"><div class="layout"><div class="panel"><h2>Gyakorlatok</h2><input id="search" type="search" placeholder="Keresés név vagy eszköz szerint…"><div class="field"><label>Szűrés</label><select id="auditFilter"><option value="all">Összes (132)</option><option value="props">Eszközös (90)</option><option value="side">Oldalfekvés</option><option value="seated">Ülés</option></select></div><div id="count" class="hint"></div><div id="results" class="scroll-list"></div></div><div class="panel"><h2 id="audTitle">Gyakorlat részletei</h2><div class="chips" id="audChips"></div><div class="gallery"><canvas width="370" height="370" id="aud0"></canvas><canvas width="370" height="370" id="aud1"></canvas></div><p class="hint" id="audDesc"></p><p class="hint">A grafika strukturális ellenőrzésre szolgál. A pontos mozdulat szakmai ellenőrzést igényel.</p></div></div></section></main><footer>A projektadatok a HTML-be vannak ágyazva, ezért ez az előnézet hálózat nélkül is megnyitható. A natív MAUI-szerkesztő forrása a ZIP-ben található.</footer>
<script>const templates=__TEMPLATES__;
const order=__ORDER__;
const exercises=__CATALOG__;
const equipment=['jógamatrac','szék','gumiszalag','kézisúlyzó','fitball','miniband','SMR-henger','jógablokk','fal','törölköző','lépcső','masszázslabda','jógapánt'];
let pose={frames:[],props:[],arrows:[],templateId:'cross-legged',view:'front',schemaVersion:1,reviewStatus:'illustrative',source:'editor-v13'};
let selected=null,drag=null,arrowBegin=null;
const $=id=>document.getElementById(id);const copy=x=>JSON.parse(JSON.stringify(x));const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function initPose(id){pose.frames=[{label:'Kiindulás',joints:copy(templates[id])},{label:'Véghelyzet',joints:copy(templates[id])}];pose.props=[];pose.arrows=[];pose.templateId=id;pose.view=['side-lying','long-sitting','supine','quadruped','child-pose','plank','lunge','wall-standing'].includes(id)?'side':'front';if(id==='chair-seated')for(let i=0;i<2;i++)pose.props.push({kind:'szék',frameIndex:i,x:50,y:76,scale:1,rotation:0});updateFrame();drawEditor();}
function updateFrame(){let s=$('frame');const prev=+(s.value||0);s.innerHTML=pose.frames.map((f,i)=>`<option value="${i}">${f.label}</option>`).join('');s.value=Math.min(prev,pose.frames.length-1);selected=null;}
function msg(t){$('status').textContent=t}
const bones=[['rightHip','rightKnee','#318486',12],['rightKnee','rightAnkle','#3d989b',10],['rightAnkle','rightToe','#493447',5],['rightShoulder','rightElbow','#df9d7e',9],['rightElbow','rightWrist','#df9d7e',7],['leftHip','leftKnee','#3c989a',12],['leftKnee','leftAnkle','#3c989a',10],['leftAnkle','leftToe','#493447',5],['leftShoulder','leftElbow','#e8ad8b',9],['leftElbow','leftWrist','#e8ad8b',7]];
function draw(c,frame,props,arrows,editing=false){let W=c.width,H=c.height;let ctx=c.getContext('2d'),u=Math.min(W,H)/112,bx=(W-100*u)/2,by=(H-100*u)/2;ctx.clearRect(0,0,W,H);ctx.fillStyle='#fbf8fe';ctx.fillRect(0,0,W,H);ctx.fillStyle='#eee5f6';ctx.beginPath();ctx.ellipse(W/2,H*.94,W*.42,8*u,0,0,Math.PI*2);ctx.fill();
const pt=(p)=>({x:bx+(p.x+p.z*.2)*u,y:by+(p.y-p.z*.07)*u});const J=frame.joints;
if(editing){ctx.strokeStyle='#e7dfef';ctx.lineWidth=1;for(let i=10;i<100;i+=10){ctx.beginPath();ctx.moveTo(bx+i*u,by);ctx.lineTo(bx+i*u,by+100*u);ctx.moveTo(bx,by+i*u);ctx.lineTo(bx+100*u,by+i*u);ctx.stroke();}}
function propdraw(q){ctx.save();let a=q.anchorA&&J[q.anchorA]?pt(J[q.anchorA]):{x:bx+q.x*u,y:by+q.y*u},x=a.x,y=a.y,s=u*q.scale;ctx.translate(x,y);ctx.rotate((q.rotation||0)*Math.PI/180);ctx.fillStyle='#8d71be';ctx.strokeStyle='#614b86';ctx.lineCap='round';ctx.lineWidth=Math.max(2,2*s);
if(q.anchorB&&J[q.anchorB]){let end=pt(J[q.anchorB]);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(end.x-x,end.y-y);ctx.lineWidth=4*s;ctx.stroke();}
else if(q.kind==='jógamatrac'){ctx.fillStyle='#cfb8de';ctx.fillRect(-36*s,-4*s,72*s,8*s)}
else if(q.kind==='szék'){ctx.fillStyle='#a491c5';ctx.fillRect(-24*s,-32*s,11*s,29*s);ctx.fillStyle='#685388';ctx.fillRect(-22*s,-8*s,46*s,7*s);ctx.fillRect(-17*s,0,4*s,22*s);ctx.fillRect(17*s,0,4*s,22*s)}
else if(q.kind==='fal'){ctx.fillStyle='#d0c2e5';ctx.fillRect(-4*s,-40*s,8*s,81*s)}
else if(q.kind==='fitball'){ctx.beginPath();ctx.arc(0,0,18*s,0,Math.PI*2);ctx.fillStyle='#4fadb0';ctx.fill();ctx.beginPath();ctx.arc(-5*s,-5*s,4*s,0,Math.PI*2);ctx.fillStyle='#a6e1d8';ctx.fill()}
else if(q.kind==='kézisúlyzó'){ctx.fillRect(-12*s,-7*s,6*s,14*s);ctx.fillRect(6*s,-7*s,6*s,14*s);ctx.fillRect(-7*s,-2*s,14*s,4*s)}
else if(q.kind==='SMR-henger'){ctx.fillStyle='#5bafaf';ctx.fillRect(-21*s,-6*s,42*s,12*s)}
else if(q.kind==='lépcső'){ctx.fillStyle='#7c62aa';ctx.fillRect(-25*s,-5*s,50*s,10*s)}
else if(q.kind==='jógablokk'){ctx.fillRect(-12*s,-9*s,24*s,18*s)}
else if(q.kind==='masszázslabda'){ctx.beginPath();ctx.arc(0,0,8*s,0,Math.PI*2);ctx.fill()}
else {ctx.beginPath();ctx.moveTo(-18*s,9*s);ctx.lineTo(0,-5*s);ctx.lineTo(18*s,9*s);ctx.stroke();}ctx.restore();}
props.filter(q=>['jógamatrac','szék','fal','fitball','lépcső'].includes(q.kind)).forEach(propdraw);
for(let i=0;i<5;i++){
 const [a,b,color,width]=bones[i],p=pt(J[a]),q=pt(J[b]);ctx.strokeStyle='#3a3146';ctx.lineWidth=(width+1)*u;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle=color;ctx.lineWidth=(width-1)*u;ctx.stroke();}
const ls=pt(J.leftShoulder),rs=pt(J.rightShoulder),lh=pt(J.leftHip),rh=pt(J.rightHip);ctx.beginPath();ctx.moveTo(ls.x,ls.y);ctx.lineTo(rs.x,rs.y);ctx.lineTo(rh.x,rh.y);ctx.lineTo(lh.x,lh.y);ctx.closePath();ctx.fillStyle='#754d90';ctx.fill();ctx.strokeStyle='#513960';ctx.lineWidth=1*u;ctx.stroke();ctx.beginPath();ctx.moveTo(ls.x+u,ls.y+u);ctx.lineTo((ls.x+rs.x)/2,(ls.y+rs.y)/2+u);ctx.lineTo((lh.x+rh.x)/2,(lh.y+rh.y)/2-u);ctx.lineTo(lh.x+u,lh.y-u);ctx.closePath();ctx.fillStyle='#a27ab2';ctx.fill();
for(let i=5;i<bones.length;i++){const[a,b,col,w]=bones[i],p=pt(J[a]),q=pt(J[b]);ctx.strokeStyle='#4a354d';ctx.lineWidth=(w+1)*u;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle=col;ctx.lineWidth=(w-1)*u;ctx.stroke();}
const neck=pt(J.neck),head=pt(J.head);ctx.strokeStyle='#e8ad8b';ctx.lineWidth=6*u;ctx.beginPath();ctx.moveTo(neck.x,neck.y);ctx.lineTo(head.x,head.y+3*u);ctx.stroke();ctx.beginPath();ctx.ellipse(head.x,head.y,7*u,9*u,0,0,Math.PI*2);ctx.fillStyle='#543645';ctx.fill();ctx.beginPath();ctx.ellipse(head.x,head.y+u,5.5*u,7*u,0,0,Math.PI*2);ctx.fillStyle='#e6a583';ctx.fill();ctx.beginPath();ctx.arc(head.x+5*u,head.y-6*u,3.6*u,0,Math.PI*2);ctx.fillStyle='#513544';ctx.fill();
props.filter(q=>!['jógamatrac','szék','fal','fitball','lépcső'].includes(q.kind)).forEach(propdraw);
for(const a of arrows){const p={x:bx+a.startX*u,y:by+a.startY*u},q={x:bx+a.endX*u,y:by+a.endY*u};ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle='#b26052';ctx.lineWidth=2.5;ctx.stroke();ctx.beginPath();ctx.arc(q.x,q.y,3,0,Math.PI*2);ctx.fillStyle='#b26052';ctx.fill()}
if(editing){for(const[k,p]of Object.entries(J)){const v=pt(p);ctx.beginPath();ctx.arc(v.x,v.y,(selected?.type==='joint'&&selected.id===k)?8:5,0,Math.PI*2);ctx.fillStyle=selected?.type==='joint'&&selected.id===k?'#f1a368':'#40a4a5';ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=2;ctx.stroke();}}
}
function drawEditor(){if(!pose.frames.length)return;const i=+$('frame').value||0;draw($('canvas'),pose.frames[i],pose.props.filter(p=>p.frameIndex===i),pose.arrows.filter(p=>p.frameIndex===i),true)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function project(anchor,original,tx,ty){const r=dist(anchor,original),len=Math.hypot(tx-anchor.x,ty-anchor.y)||1;return {...original,x:anchor.x+(tx-anchor.x)*r/len,y:anchor.y+(ty-anchor.y)*r/len}}
const parent={leftElbow:'leftShoulder',rightElbow:'rightShoulder',leftWrist:'leftElbow',rightWrist:'rightElbow',leftKnee:'leftHip',rightKnee:'rightHip',leftAnkle:'leftKnee',rightAnkle:'rightKnee',leftToe:'leftAnkle',rightToe:'rightAnkle',head:'neck'};
const following={leftElbow:['leftWrist'],rightElbow:['rightWrist'],leftKnee:['leftAnkle','leftToe'],rightKnee:['rightAnkle','rightToe'],leftAnkle:['leftToe'],rightAnkle:['rightToe'],leftShoulder:['leftElbow','leftWrist'],rightShoulder:['rightElbow','rightWrist'],leftHip:['leftKnee','leftAnkle','leftToe'],rightHip:['rightKnee','rightAnkle','rightToe'],neck:['head']};
const longBones=[['leftShoulder','leftElbow'],['rightShoulder','rightElbow'],['leftElbow','leftWrist'],['rightElbow','rightWrist'],['leftHip','leftKnee'],['rightHip','rightKnee'],['leftKnee','leftAnkle'],['rightKnee','rightAnkle']];
function bendCross(a,b,c){return (b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x)}
function moveJoint(joints,k,x,y){const before=copy(joints),orig=before[k],p=parent[k],next=p?project(before[p],orig,x,y):{...orig,x,y};const dx=next.x-orig.x,dy=next.y-orig.y;let output=copy(before);output[k]=next;const group=following[k]||[];if(group.length&&(k.endsWith('Elbow')||k.endsWith('Knee')||k.endsWith('Ankle')||!p)){for(const name of group){const q=output[name];output[name]={...q,x:q.x+dx,y:q.y+dy}}}
if(Object.values(output).some(q=>q.x<1||q.x>99||q.y<1||q.y>99))return 'Az ábra széléhez értél.';
for(const[a,b]of longBones)if(Math.abs(dist(output[a],output[b])-dist(before[a],before[b]))>.35)return 'A végtag nem nyújtható meg.';
for(const side of ['left','right'])for(const [a,b,c]of [[side+'Shoulder',side+'Elbow',side+'Wrist'],[side+'Hip',side+'Knee',side+'Ankle']]){const first=bendCross(before[a],before[b],before[c]),other=bendCross(output[a],output[b],output[c]);if(Math.abs(first)>dist(before[a],before[b])*dist(before[b],before[c])*.13&&first*other<0)return 'A hajlat nem fordulhat át.';}
for(const [a,b] of [['leftShoulder','leftHip'],['rightShoulder','rightHip'],['leftShoulder','rightShoulder'],['leftHip','rightHip']]){const o=dist(before[a],before[b]),n=dist(output[a],output[b]);if(o>2&&(n/o<.72||n/o>1.28))return 'A törzs aránya nem tartható.';}
Object.assign(joints,output);return null;}
function canvasPoint(ev){const r=$('canvas').getBoundingClientRect(),x=(ev.clientX-r.left)/r.width*560,y=(ev.clientY-r.top)/r.height*560,u=560/112,bx=(560-100*u)/2,by=bx;return{x:clamp((x-bx)/u,0,100),y:clamp((y-by)/u,0,100)}}
function addingProp(kind){let i=+$('frame').value||0,j=pose.frames[i].joints,q={kind,frameIndex:i,x:50,y:75,scale:1,rotation:0};if(kind==='jógamatrac')Object.assign(q,{x:50,y:92,scale:1.15});if(kind==='fitball')Object.assign(q,{x:50,y:77});if(kind==='szék')Object.assign(q,{x:50,y:76});if(kind==='fal')Object.assign(q,{x:88,y:50});if(kind==='SMR-henger')Object.assign(q,{x:50,y:85});if(kind==='kézisúlyzó')Object.assign(q,{x:j.leftWrist.x,y:j.leftWrist.y,anchorA:'leftWrist',scale:.75});if(kind==='gumiszalag'||kind==='jógapánt'||kind==='miniband'){q.anchorA=kind==='miniband'?'leftKnee':'leftWrist';q.anchorB=kind==='miniband'?'rightKnee':'rightWrist';q.x=j[q.anchorA].x;q.y=j[q.anchorA].y;}pose.props.push(q);selected={type:'prop',id:pose.props.length-1};$('mode').value='prop';$('scale').value=q.scale;$('rotation').value=q.rotation;drawEditor();msg('Eszköz hozzáadva. Húzhatod és forgathatod.');}
$('canvas').addEventListener('pointerdown',e=>{let point=canvasPoint(e),i=+$('frame').value||0,mode=$('mode').value,j=pose.frames[i].joints;
if(mode==='arrow'){if(!arrowBegin){arrowBegin=point;msg('Jelöld ki a nyíl végét is.')}else{pose.arrows.push({frameIndex:i,type:'line',startX:arrowBegin.x,startY:arrowBegin.y,endX:point.x,endY:point.y});arrowBegin=null;msg('Mozgásnyíl hozzáadva.')}drawEditor();return;}
if(mode==='points'){let nearest=Object.entries(j).map(([k,p])=>[k,dist(p,point)]).sort((a,b)=>a[1]-b[1])[0];if(nearest&&nearest[1]<9){selected={type:'joint',id:nearest[0]};drag=selected;}}else{let nearest=pose.props.map((q,k)=>[k,q.frameIndex===i?dist(q.anchorA?j[q.anchorA]:q,point):Infinity]).sort((a,b)=>a[1]-b[1])[0];if(nearest&&nearest[1]<15){selected={type:'prop',id:nearest[0]};drag=selected;$('scale').value=pose.props[selected.id].scale;$('rotation').value=pose.props[selected.id].rotation;}}
if(drag)$('canvas').setPointerCapture(e.pointerId);drawEditor();});
$('canvas').addEventListener('pointermove',e=>{if(!drag)return;let p=canvasPoint(e),i=+$('frame').value||0;if(drag.type==='joint'){let err=moveJoint(pose.frames[i].joints,drag.id,p.x,p.y);if(err)msg(err);else msg('Testpont módosítva – arányvédelemmel.')}else{let q=pose.props[drag.id];if(q.anchorA){msg('A testponthoz kötött eszközt a testpont húzásával mozgathatod.');return;}q.x=p.x;q.y=p.y;}drawEditor();});
$('canvas').addEventListener('pointerup',()=>drag=null);$('canvas').addEventListener('pointercancel',()=>drag=null);
$('scale').addEventListener('input',()=>{if(selected?.type==='prop'){pose.props[selected.id].scale=clamp(+$('scale').value,.5,1.6);drawEditor()}});
$('rotation').addEventListener('input',()=>{if(selected?.type==='prop'){pose.props[selected.id].rotation=clamp(+$('rotation').value,-180,180);drawEditor()}});
$('addEq').onclick=()=>addingProp($('equipment').value);$('removeEq').onclick=()=>{if(selected?.type==='prop'){pose.props.splice(selected.id,1);selected=null;drawEditor();msg('Eszköz eltávolítva.')}};
$('loadTemplate').onclick=()=>{if(!confirm('A jelenlegi ábra adatai lecserélődnek a kiválasztott sablonra. Folytatod?'))return;initPose($('template').value);msg('A sablon betöltve.')};
$('newFrame').onclick=()=>{if(pose.frames.length>=6){msg('Legfeljebb hat mozgásfázis lehet.');return;}let old=+$('frame').value||0,n=pose.frames.length;pose.frames.push({label:(n+1)+'. fázis',joints:copy(pose.frames[old].joints)});pose.props.push(...pose.props.filter(q=>q.frameIndex===old).map(q=>({...copy(q),frameIndex:n})));updateFrame();$('frame').value=n;drawEditor()};
$('frame').onchange=()=>{selected=null;drawEditor()};$('reset').onclick=()=>{if(confirm('A szerkesztést visszaállítod a sablonra?'))initPose($('template').value)};
$('export').onclick=()=>{let data=new Blob([JSON.stringify(pose,null,2)],{type:'application/json'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='mozdulj-poz.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);msg('A póz JSON mentése elindult.')};
for(const[id,name]of order){let op=document.createElement('option');op.value=id;op.textContent=name;$('template').append(op)}
for(const t of equipment){let op=document.createElement('option');op.value=t;op.textContent=t;$('equipment').append(op)}
$('template').value='cross-legged';initPose('cross-legged');
let selectedExercise=null;
function auditSelect(e){selectedExercise=e;document.querySelectorAll('.entry').forEach(btn=>btn.classList.toggle('on',btn.dataset.id===e.id));$('audTitle').textContent=e.name;$('audChips').innerHTML=[e.category,...e.regions,...e.equipment].map(s=>`<span class="chip">${s.replace(/</g,'&lt;')}</span>`).join('');$('audDesc').textContent=e.startingPosition+' '+(e.steps?.[0]||'');for(let i=0;i<2;i++){let f=e.pose.frames[Math.min(i,e.pose.frames.length-1)];draw($('aud'+i),f,(e.pose.props||[]).filter(p=>p.frameIndex===i),(e.pose.arrows||[]).filter(a=>a.frameIndex===i),false)}}
function auditList(){let search=$('search').value.toLocaleLowerCase('hu'),filter=$('auditFilter').value;let items=exercises.filter(e=>{if(filter==='props'&&!e.equipment.length)return false;if(filter==='side'&&!e.id.includes('oldalfek'))return false;if(filter==='seated'&&!/ül|szék|fitball/i.test(e.name))return false;return(e.name+' '+e.equipment.join(' ')).toLocaleLowerCase('hu').includes(search)});$('count').textContent=items.length+' találat';$('results').innerHTML='';for(const e of items){let b=document.createElement('button');b.className='entry';b.dataset.id=e.id;b.textContent=e.name+' · '+e.category;if(selectedExercise?.id===e.id)b.classList.add('on');b.onclick=()=>auditSelect(e);$('results').append(b)}if(items.length&&!items.some(x=>x.id===selectedExercise?.id))auditSelect(items[0]);}
$('search').oninput=auditList;$('auditFilter').onchange=auditList;auditList();
document.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('on',e===btn));document.querySelectorAll('main section').forEach(s=>s.classList.toggle('on',s.id===btn.dataset.tab));if(btn.dataset.tab==='audit'&&selectedExercise)auditSelect(selectedExercise);else drawEditor()});
</script></body></html>'''
